// scripts/bundle-worker.js
// Bundle worker code separately

import fs from 'fs';
import path from 'path';
import { execSync } from 'child_process';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

console.log(' Building worker bundle...\n');

const distDir = path.join(__dirname, '../dist');
if (!fs.existsSync(distDir)) {
  console.log(' Creating dist directory...');
  fs.mkdirSync(distDir, { recursive: true });
}

// Build worker bundle with rollup
console.log('📦 Bundling worker with Rollup...');
try {
  // Use rollup config with worker entry
  execSync('npx rollup -c --configWorker', {
    stdio: 'inherit',
    env: { ...process.env, NODE_ENV: 'production' },
  });
  console.log('        Worker bundle complete\n');
} catch (err) {
  console.error('        Worker bundle failed:', err.message);
  process.exit(1);
}

// Create a simple worker bundle for inline use
try {
  const workerSrc = path.join(distDir, 'dotjs.worker.js');
  if (fs.existsSync(workerSrc)) {
    const workerCode = fs.readFileSync(workerSrc, 'utf8');

    // Create a version that can be inlined
    const inlineWorker = `// dot.js Worker - Inline Version
// This file is automatically generated
// Can be used for inline worker creation

${workerCode}

// Export for usage
if (typeof self !== 'undefined') {
  self.DotWorker = self.DotWorker || {};
}
`;
    const inlinePath = path.join(distDir, 'dotjs.worker.inline.js');
    fs.writeFileSync(inlinePath, inlineWorker);
    console.log('        Inline worker version created:', inlinePath);

    // Also create a blob URL version
    const blobWorker = `// dot.js Worker - Blob URL Version
// This file is automatically generated
// Use: URL.createObjectURL(new Blob([code], {type: 'application/javascript'}))

${workerCode}
`;
    const blobPath = path.join(distDir, 'dotjs.worker.blob.js');
    fs.writeFileSync(blobPath, blobWorker);
    console.log('        Blob worker version created:', blobPath);
  }
} catch (err) {
  console.error('        Failed to create worker versions:', err.message);
}

// Generate worker size report
try {
  const workerFiles = fs.readdirSync(distDir).filter((f) => f.includes('worker'));
  console.log('\n Worker bundle sizes:');
  console.log('─'.repeat(40));

  for (const file of workerFiles) {
    const filePath = path.join(distDir, file);
    const stats = fs.statSync(filePath);
    const sizeKB = (stats.size / 1024).toFixed(2);
    console.log(`          ${file.padEnd(30)} ${sizeKB} KB`);
  }
  console.log('─'.repeat(40));
} catch (err) {
  console.error('        Failed to generate worker size report:', err.message);
}

console.log('\n Worker bundle complete!');